#!/usr/bin/env node
/** Regenerates src/diagnostics/roslyn-codes.js from the pinned Roslyn resource dump.
 * The generated table keeps every code it already lists, adds each CSxxxx literal found under
 * packages/compiler/src, and adds any codes passed on the command line (`node generate-diagnostic-codes.js CS0104 CS0234`).
 * `--check` exits non-zero when the generated file is stale instead of writing it.
 */
import {readFileSync,writeFileSync,readdirSync,existsSync} from 'node:fs';
import {dirname,resolve,join} from 'node:path';
import {fileURLToPath} from 'node:url';
const root=resolve(dirname(fileURLToPath(import.meta.url)),'..'),target=join(root,'src/diagnostics/roslyn-codes.js');
const dump=JSON.parse(readFileSync(join(root,'test/roslyn/diagnostic-messages.json'),'utf8'));
const wanted=new Set(process.argv.slice(2).filter(a=>/^CS\d{4}$/.test(a)));
if(existsSync(target))for(const m of readFileSync(target,'utf8').matchAll(/^ (CS\d{4}):/gm))wanted.add(m[1]);
const visit=dir=>{for(const e of readdirSync(dir,{withFileTypes:true})){const p=join(dir,e.name);if(e.isDirectory())visit(p);else if(e.name.endsWith('.js')&&p!==target)for(const m of readFileSync(p,'utf8').matchAll(/\bCS\d{4}\b/g))wanted.add(m[0]);}};
visit(join(root,'src'));
const missing=[...wanted].filter(c=>!dump.codes[c]).sort();
if(missing.length)console.error('Not in the pinned Roslyn dump (kept out of the table): '+missing.join(' '));
const rows=[...wanted].filter(c=>dump.codes[c]).sort().map(c=>{const [name,severity,level,format]=dump.codes[c];return ` ${c}:[${JSON.stringify(name)},${JSON.stringify(severity)},${level},${JSON.stringify(format)}]`;});
const text=`/** GENERATED by packages/compiler/scripts/generate-diagnostic-codes.js from the pinned Roslyn ${dump.roslyn} resource dump. Do not edit.\n * Row shape: code:[Roslyn ErrorCode name, default severity, warning level, message format]. */\nexport const ROSLYN_VERSION=${JSON.stringify(dump.roslyn)};\nexport const roslynCodes=Object.freeze({\n${rows.join(',\n')}\n});\n`;
if(process.argv.includes('--check')){if(!existsSync(target)||readFileSync(target,'utf8')!==text){console.error('roslyn-codes.js is stale; run packages/compiler/scripts/generate-diagnostic-codes.js');process.exit(1);}}
else{writeFileSync(target,text);console.log(`Wrote ${rows.length} Roslyn diagnostic descriptors.`);}
